WITH parsed AS (SELECT id, service, host, log_ts, level, status_code, payload_json, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, SIZE(context) AS num_context FROM app_logs WHERE TO_DATE(log_ts) < '2025-01-01') SELECT id, service, log_ts, level, has_region, num_context, NTILE(5) OVER (PARTITION BY MONTH(log_ts) ORDER BY num_context DESC, id) AS num_context_bucket, NTILE(10) OVER (PARTITION BY service ORDER BY status_code, id) AS status_code_bucket, SUM(num_context) OVER (PARTITION BY host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS num_context_sum_2h, LEAD(status_code, 2) OVER (PARTITION BY service ORDER BY log_ts, id) AS next_status_code, LEAD(status_code, 2) OVER (PARTITION BY YEAR(log_ts), service ORDER BY num_context, id) AS next_status_code_2 FROM parsed WHERE status_code >= 323;
